def breaks(inp: str) -> bool:
    try:
        a = [int(t) for t in inp.split()]
    except ValueError:
        raise ValueError("enter whole numbers separated by spaces")
    if not 1 <= len(a) <= 8:
        raise ValueError("enter 1 to 8 numbers")
    if any(x < 1 or x > 100 for x in a):
        raise ValueError("values must be between 1 and 100")
    seen = {}

    def winners(state):
        # state: sorted tuple of (player, tokens) still alive
        if state in seen:
            return seen[state]
        if len(state) == 1:
            res = frozenset([state[0][0]])
        else:
            out = set()
            for i in range(len(state)):
                for j in range(i + 1, len(state)):
                    (pi, ti), (pj, tj) = state[i], state[j]
                    rest = [s for k, s in enumerate(state) if k != i and k != j]
                    if ti >= tj:
                        out |= winners(tuple(sorted(rest + [(pi, ti + tj)])))
                    if tj >= ti:
                        out |= winners(tuple(sorted(rest + [(pj, ti + tj)])))
            res = frozenset(out)
        seen[state] = res
        return res

    truth = winners(tuple(sorted(enumerate(a))))
    for p in range(len(a)):
        higher = [x for x in a if x > a[p]]
        local = (not higher) or sum(x for x in a if x <= a[p]) >= min(higher)
        if local != (p in truth):
            return True
    return False

