        start = tuple(a)
        seen = {start}
        frontier = [start]
        d = 0
        while True:
            for s in frontier:
                if len(set(s)) == 1:
                    return d
            nxt = []
            for s in frontier:
                for i in range(len(s)):
                    for j in (i - 1, i + 1):
                        if 0 <= j < len(s):
                            t = list(s)
                            t[j] += t[i]
                            del t[i]
                            t = tuple(t)
                            if t not in seen:
                                seen.add(t)
                                nxt.append(t)
            frontier = nxt
            d += 1
    n = len(a)
    m = max(a)
    return n > 1 and a.count(m) == 1 and min_ops(a) < n - 1

